package com.universe.auth.controller; import com.universe.auth.dto.request.*; import com.universe.auth.dto.response.*; import com.universe.auth.service.AuthService; import com.universe.global.common.ApiResponse; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") @RequiredArgsConstructor public class AuthController { private final AuthService service; @PostMapping("/signup") public ApiResponse<SignupResponse> signup(@Valid @RequestBody SignupRequest r){return ApiResponse.success(service.signup(r));} @PostMapping("/login") public ApiResponse<LoginResponse> login(@Valid @RequestBody LoginRequest r){return ApiResponse.success(service.login(r));} @PostMapping("/refresh") public ApiResponse<TokenResponse> refresh(@Valid @RequestBody RefreshRequest r){return ApiResponse.success(service.refresh(r));} @PostMapping("/logout") public ApiResponse<Void> logout(){service.logout();return ApiResponse.success();} }
